package com.craftcost;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(CraftCostConfig.CONFIG_GROUP)
public interface CraftCostConfig extends Config
{
	String CONFIG_GROUP = "craftcost";

	@ConfigItem(
		keyName = "autoShowGeItem",
		name = "Auto-show GE item",
		description = "When you're looking at an item's price at the Grand Exchange and it's one of your known recipes, " +
			"automatically add it to the watchlist panel."
	)
	default boolean autoShowGeItem()
	{
		return false;
	}

	@ConfigItem(
		keyName = "countBank",
		name = "Count bank items",
		description = "Include items sitting in your bank (not just your inventory) as 'owned' when working out how many you'd still need to buy. " +
			"Note the client only knows your bank's contents once you've opened your bank at least once this session."
	)
	default boolean countBank()
	{
		return true;
	}

	@ConfigItem(
		keyName = "countInventory",
		name = "Count inventory items",
		description = "Include items in your inventory as 'owned' when working out how many you'd still need to buy."
	)
	default boolean countInventory()
	{
		return true;
	}

	@ConfigItem(
		keyName = "debugGeOffer",
		name = "Log GE offer screen (debug)",
		description = "Writes every variable that changes while a Grand Exchange offer screen is open, plus the text on " +
			"that screen, to the client log. Only useful for working out where the game keeps the offer price after a " +
			"client update moves it. Leave this off."
	)
	default boolean debugGeOffer()
	{
		return false;
	}
}

package com.craftcost;

import java.awt.BorderLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.DefaultListModel;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import javax.swing.ListSelectionModel;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

class CraftCostPanel extends PluginPanel
{
	private static final int MAX_SEARCH_RESULTS = 30;

	private final CraftCostPlugin plugin;
	private final ItemManager itemManager;
	private final ClientThread clientThread;

	private final JTextField searchField = new JTextField();
	private final DefaultListModel<Recipe> searchResultsModel = new DefaultListModel<>();
	private final JList<Recipe> searchResultsList = new JList<>(searchResultsModel);
	private final JScrollPane searchResultsScroll = new JScrollPane(searchResultsList);
	private final JCheckBox autoShowCheckbox = new JCheckBox("Auto-show GE item");
	private final JPanel cardsContainer = new JPanel();
	private final JLabel emptyStateLabel = new JLabel(
		"<html><center>Nothing in your watchlist yet.<br>Search for an item above, "
			+ "or turn on auto-show and browse one at the GE.</center></html>");

	private final Map<Integer, RecipeCardPanel> cardsByItemId = new LinkedHashMap<>();
	private boolean loading;

	CraftCostPanel(CraftCostPlugin plugin, ItemManager itemManager, ClientThread clientThread)
	{
		super();
		this.plugin = plugin;
		this.itemManager = itemManager;
		this.clientThread = clientThread;

		setLayout(new BorderLayout(0, 6));

		add(buildControls(), BorderLayout.NORTH);

		cardsContainer.setLayout(new BoxLayout(cardsContainer, BoxLayout.Y_AXIS));
		cardsContainer.setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(cardsContainer, BorderLayout.CENTER);

		emptyStateLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		emptyStateLabel.setFont(FontManager.getRunescapeSmallFont());
		emptyStateLabel.setHorizontalAlignment(SwingConstants.CENTER);
		emptyStateLabel.setBorder(new EmptyBorder(16, 4, 0, 4));

		loadPersistedWatchlist();
		updateEmptyState();
	}

	private JPanel buildControls()
	{
		JPanel controls = new JPanel();
		controls.setLayout(new BoxLayout(controls, BoxLayout.Y_AXIS));
		controls.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JLabel searchLabel = new JLabel("Add to watchlist");
		searchLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		searchLabel.setFont(FontManager.getRunescapeSmallFont());
		searchLabel.setAlignmentX(LEFT_ALIGNMENT);
		controls.add(searchLabel);
		controls.add(Box.createVerticalStrut(2));

		searchField.setFont(FontManager.getRunescapeSmallFont());
		searchField.setToolTipText("Type an item name to search everything this plugin knows how to make");
		searchField.setAlignmentX(LEFT_ALIGNMENT);
		searchField.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				updateSearchResults();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				updateSearchResults();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				updateSearchResults();
			}
		});
		searchField.addActionListener(e -> addFirstSearchResult());
		controls.add(searchField);

		searchResultsList.setFont(FontManager.getRunescapeSmallFont());
		searchResultsList.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		searchResultsList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
		searchResultsList.setVisibleRowCount(6);
		searchResultsList.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				int index = searchResultsList.locationToIndex(e.getPoint());
				if (index >= 0)
				{
					addFromSearch(searchResultsModel.getElementAt(index));
				}
			}
		});

		searchResultsScroll.setAlignmentX(LEFT_ALIGNMENT);
		searchResultsScroll.setBorder(null);
		searchResultsScroll.setVisible(false);
		controls.add(searchResultsScroll);

		controls.add(Box.createVerticalStrut(4));

		autoShowCheckbox.setBackground(ColorScheme.DARK_GRAY_COLOR);
		autoShowCheckbox.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		autoShowCheckbox.setFont(FontManager.getRunescapeSmallFont());
		autoShowCheckbox.setToolTipText("While on, browsing a known recipe's price at the Grand Exchange adds it here automatically.");
		autoShowCheckbox.setSelected(plugin.isAutoShowGeItem());
		autoShowCheckbox.addActionListener(e -> plugin.setAutoShowGeItem(autoShowCheckbox.isSelected()));

		JButton refreshAll = new JButton("⟳");
		refreshAll.setToolTipText("Refresh all prices and owned counts");
		refreshAll.addActionListener(e -> onOwnedItemsChanged());

		JPanel toggleRow = new JPanel(new BorderLayout(4, 0));
		toggleRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
		toggleRow.add(autoShowCheckbox, BorderLayout.CENTER);
		toggleRow.add(refreshAll, BorderLayout.EAST);
		controls.add(toggleRow);

		return controls;
	}

	/**
	 * Filters {@link RecipeDatabase#RECIPES} by whatever's typed in the search
	 * box (case-insensitive substring match on item name) and shows the
	 * matches below it, capped at {@link #MAX_SEARCH_RESULTS} so one very
	 * broad query (e.g. "potion") doesn't dump hundreds of rows at once.
	 */
	private void updateSearchResults()
	{
		String query = searchField.getText().trim().toLowerCase(Locale.ROOT);
		searchResultsModel.clear();

		if (!query.isEmpty())
		{
			for (Recipe recipe : RecipeDatabase.RECIPES)
			{
				if (recipe.getItemName().toLowerCase(Locale.ROOT).contains(query))
				{
					searchResultsModel.addElement(recipe);
					if (searchResultsModel.size() >= MAX_SEARCH_RESULTS)
					{
						break;
					}
				}
			}
		}

		searchResultsScroll.setVisible(!searchResultsModel.isEmpty());
		revalidate();
		repaint();
	}

	private void addFromSearch(Recipe recipe)
	{
		addRecipe(recipe);
		searchField.setText("");
		searchResultsModel.clear();
		searchResultsScroll.setVisible(false);
		revalidate();
		repaint();
	}

	private void addFirstSearchResult()
	{
		if (!searchResultsModel.isEmpty())
		{
			addFromSearch(searchResultsModel.getElementAt(0));
		}
	}

	private void loadPersistedWatchlist()
	{
		loading = true;
		for (int itemId : plugin.loadWatchlist())
		{
			Recipe recipe = RecipeDatabase.findByItemId(itemId);
			if (recipe != null)
			{
				addRecipe(recipe);
			}
		}
		loading = false;
	}

	/**
	 * Called by the plugin when a known recipe is spotted at the GE while
	 * "Auto-show GE item" is on. Runs on the client thread, so hop to the EDT.
	 */
	void autoAddFromGe(Recipe recipe)
	{
		SwingUtilities.invokeLater(() -> addRecipe(recipe));
	}

	/**
	 * Called by the plugin when the Grand Exchange offer quantity changes for
	 * a recipe already known to the panel, while auto-show is on. Runs on
	 * the client thread, so hop to the EDT. A no-op if that recipe isn't
	 * (yet) in the watchlist.
	 */
	void autoSetAmount(Recipe recipe, int amount)
	{
		SwingUtilities.invokeLater(() ->
		{
			RecipeCardPanel card = cardsByItemId.get(recipe.getItemId());
			if (card != null)
			{
				card.setAmount(amount);
			}
		});
	}

	/**
	 * Called by the plugin when the Grand Exchange offer price-per-item
	 * changes for a recipe already known to the panel, while auto-show is on.
	 * Runs on the client thread, so hop to the EDT. A no-op if that recipe
	 * isn't (yet) in the watchlist.
	 */
	void autoSetPrice(Recipe recipe, int price)
	{
		SwingUtilities.invokeLater(() ->
		{
			RecipeCardPanel card = cardsByItemId.get(recipe.getItemId());
			if (card != null)
			{
				card.setLivePrice(price);
			}
		});
	}

	private void addRecipe(Recipe recipe)
	{
		if (cardsByItemId.containsKey(recipe.getItemId()))
		{
			return;
		}

		RecipeCardPanel card = new RecipeCardPanel(recipe, plugin, itemManager, clientThread, () -> removeRecipe(recipe));
		cardsByItemId.put(recipe.getItemId(), card);
		cardsContainer.add(card);
		cardsContainer.add(Box.createVerticalStrut(6));

		persistWatchlist();
		updateEmptyState();
		cardsContainer.revalidate();
		cardsContainer.repaint();
	}

	private void removeRecipe(Recipe recipe)
	{
		RecipeCardPanel card = cardsByItemId.remove(recipe.getItemId());
		if (card == null)
		{
			return;
		}

		int index = cardsContainer.getComponentZOrder(card);
		cardsContainer.remove(card);
		// remove the spacer strut that follows the card, if it's still there
		if (index >= 0 && index < cardsContainer.getComponentCount())
		{
			cardsContainer.remove(index);
		}

		persistWatchlist();
		updateEmptyState();
		cardsContainer.revalidate();
		cardsContainer.repaint();
	}

	private void persistWatchlist()
	{
		if (loading)
		{
			return;
		}
		plugin.saveWatchlist(new ArrayList<>(cardsByItemId.keySet()));
	}

	private void updateEmptyState()
	{
		boolean empty = cardsByItemId.isEmpty();
		if (empty && emptyStateLabel.getParent() == null)
		{
			cardsContainer.add(emptyStateLabel);
		}
		else if (!empty && emptyStateLabel.getParent() != null)
		{
			cardsContainer.remove(emptyStateLabel);
		}
	}

	/**
	 * Called by the plugin when the Grand Exchange offer screen closes, so no
	 * card is left showing a price from an offer that isn't on screen any more.
	 */
	void autoClearLivePrices()
	{
		SwingUtilities.invokeLater(() ->
		{
			for (RecipeCardPanel card : cardsByItemId.values())
			{
				card.clearLivePrice();
			}
		});
	}

	/**
	 * Called by the plugin whenever inventory/bank contents change, so every
	 * card in the watchlist stays up to date without a manual refresh.
	 */
	void onOwnedItemsChanged()
	{
		SwingUtilities.invokeLater(() ->
		{
			for (RecipeCardPanel card : cardsByItemId.values())
			{
				card.refresh();
			}
		});
	}
}

package com.craftcost;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Craft Cost Comparator",
	description = "Compares an item's Grand Exchange price against the cost of its ingredients, counting what you already have banked (Herblore potions)",
	tags = {"grand", "exchange", "ge", "herblore", "potion", "profit", "cost", "craft", "skilling"}
)
public class CraftCostPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private CraftCostConfig config;

	@Inject
	private ConfigManager configManager;

	private static final String WATCHLIST_KEY = "watchlist";

	private final Map<Integer, Integer> inventoryCounts = new ConcurrentHashMap<>();
	private final Map<Integer, Integer> bankCounts = new ConcurrentHashMap<>();

	private final GeOfferPrice geOfferPrice = new GeOfferPrice();

	private boolean geOfferScreenOpen;

	/** Last price pushed to the panel, so an unchanged one isn't pushed again. */
	private int lastLivePrice;

	private CraftCostPanel panel;
	private NavigationButton navButton;

	@Override
	protected void startUp()
	{
		panel = new CraftCostPanel(this, itemManager, clientThread);

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");

		navButton = NavigationButton.builder()
			.tooltip("Craft Cost Comparator")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);

		// If the plugin is enabled while already logged in, grab whatever
		// container contents the client already has cached.
		clientThread.invoke(() ->
		{
			refreshContainer(InventoryID.INV, inventoryCounts);
			refreshContainer(InventoryID.BANK, bankCounts);
		});
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		inventoryCounts.clear();
		bankCounts.clear();
		geOfferScreenOpen = false;
		lastLivePrice = 0;
		geOfferPrice.reset();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invoke(() ->
			{
				refreshContainer(InventoryID.INV, inventoryCounts);
				refreshContainer(InventoryID.BANK, bankCounts);
			});
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			inventoryCounts.clear();
			bankCounts.clear();
			geOfferScreenOpen = false;
			lastLivePrice = 0;
			geOfferPrice.reset();
			panel.autoClearLivePrices();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.INV)
		{
			rebuildCounts(event.getItemContainer(), inventoryCounts);
			panel.onOwnedItemsChanged();
		}
		else if (event.getContainerId() == InventoryID.BANK)
		{
			rebuildCounts(event.getItemContainer(), bankCounts);
			panel.onOwnedItemsChanged();
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.GE_OFFERS)
		{
			geOfferScreenOpen = true;
			geOfferPrice.onScreenOpened(client);
			checkGeItem();
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.GE_OFFERS)
		{
			geOfferScreenOpen = false;
			lastLivePrice = 0;
			// The cards label this price as the one on a live offer, so it stops
			// being true the moment the offer screen goes away - whether the
			// offer was confirmed or abandoned. Drop back to the guide price
			// rather than leaving a stale number sitting there.
			panel.autoClearLivePrices();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (!geOfferScreenOpen)
		{
			return;
		}

		geOfferPrice.onVarChanged(client, config.debugGeOffer());

		if (event.getVarpId() == VarPlayerID.TRADINGPOST_SEARCH)
		{
			// Picking an item is what builds the offer-setup screen, so it's the
			// cue for the debug dump - a couple of ticks later, once it exists.
			// Outside checkGeItem deliberately: that returns early when
			// auto-show is off, and a diagnostic shouldn't depend on a setting
			// unrelated to what it's diagnosing.
			geOfferPrice.requestWatch();
			checkGeItem();
			return;
		}

		if (event.getVarbitId() == VarbitID.GE_NEWOFFER_QUANTITY)
		{
			checkGeQuantity();
		}
	}

	/**
	 * Adjusting the price writes no game variable at all, so there is no event to
	 * subscribe to - it has to be read off the screen on a pulse. A client tick
	 * is about 20ms, which makes the card feel like it moves with the buttons,
	 * and the work is a widget lookup and a short string parse.
	 */
	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (geOfferScreenOpen)
		{
			checkGePrice();
		}
	}

	private void checkGeItem()
	{
		if (!config.autoShowGeItem())
		{
			return;
		}

		// TRADINGPOST_SEARCH tracks the item you're currently viewing/buying at
		// the GE live, including while the offer-setup screen is open - unlike
		// the GE_LAST_OFFER_* varps, which only update once an offer is submitted.
		int itemId = client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH);
		Recipe recipe = RecipeDatabase.findByItemId(itemId);
		if (recipe != null)
		{
			panel.autoAddFromGe(recipe);
			// Pick up the quantity already showing, not just future changes.
			// Deliberately not the price: nothing has been typed for this item
			// yet, so the price varbit still holds the previous offer's value.
			checkGeQuantity();
		}
	}

	private void checkGeQuantity()
	{
		if (!config.autoShowGeItem())
		{
			return;
		}

		int itemId = client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH);
		Recipe recipe = RecipeDatabase.findByItemId(itemId);
		if (recipe == null)
		{
			return;
		}

		// GE_NEWOFFER_QUANTITY is a varbit that updates live, tick by tick, as
		// the quantity box on the offer-setup screen is typed into or clicked -
		// confirmed by watching it in RuneLite's Var Inspector while adjusting
		// the quantity before submitting.
		int quantity = client.getVarbitValue(VarbitID.GE_NEWOFFER_QUANTITY);
		if (quantity > 0)
		{
			panel.autoSetAmount(recipe, quantity);
		}
	}

	private void checkGePrice()
	{
		if (!config.autoShowGeItem())
		{
			return;
		}

		int itemId = client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH);
		Recipe recipe = RecipeDatabase.findByItemId(itemId);
		if (recipe == null)
		{
			return;
		}

		// Reads the price-per-item box off the offer-setup screen. See
		// GeOfferPrice for why this isn't read from a game variable.
		int price = geOfferPrice.read(client);
		if (price == lastLivePrice)
		{
			return;
		}

		lastLivePrice = price;
		if (price > 0)
		{
			panel.autoSetPrice(recipe, price);
		}
		else
		{
			// The setup screen has gone, so there is no live price any more.
			panel.autoClearLivePrices();
		}
	}

	/**
	 * Whether the panel's "Auto-show GE item" checkbox should be ticked -
	 * lets the panel stay in sync with the plugin's own config panel entry.
	 */
	boolean isAutoShowGeItem()
	{
		return config.autoShowGeItem();
	}

	void setAutoShowGeItem(boolean value)
	{
		configManager.setConfiguration(CraftCostConfig.CONFIG_GROUP, "autoShowGeItem", String.valueOf(value));
	}

	/**
	 * Item ids of whatever's currently in the watchlist, persisted across
	 * client restarts.
	 */
	List<Integer> loadWatchlist()
	{
		String csv = configManager.getConfiguration(CraftCostConfig.CONFIG_GROUP, WATCHLIST_KEY);
		List<Integer> ids = new ArrayList<>();
		if (csv != null && !csv.isEmpty())
		{
			for (String part : csv.split(","))
			{
				try
				{
					ids.add(Integer.parseInt(part.trim()));
				}
				catch (NumberFormatException e)
				{
					// ignore a corrupted entry rather than losing the whole list
				}
			}
		}
		return ids;
	}

	void saveWatchlist(List<Integer> itemIds)
	{
		String csv = itemIds.stream().map(String::valueOf).collect(Collectors.joining(","));
		configManager.setConfiguration(CraftCostConfig.CONFIG_GROUP, WATCHLIST_KEY, csv);
	}

	private void refreshContainer(int containerId, Map<Integer, Integer> target)
	{
		ItemContainer container = client.getItemContainer(containerId);
		if (container != null)
		{
			rebuildCounts(container, target);
		}
	}

	private void rebuildCounts(ItemContainer container, Map<Integer, Integer> target)
	{
		target.clear();
		for (Item item : container.getItems())
		{
			if (item.getId() <= 0 || item.getQuantity() <= 0)
			{
				continue;
			}
			target.merge(item.getId(), item.getQuantity(), Integer::sum);
		}
	}

	/**
	 * How many of the given item Chris currently owns, per the "count bank" /
	 * "count inventory" config toggles.
	 */
	int getOwnedCount(int itemId)
	{
		int total = 0;
		if (config.countInventory())
		{
			total += inventoryCounts.getOrDefault(itemId, 0);
		}
		if (config.countBank())
		{
			total += bankCounts.getOrDefault(itemId, 0);
		}
		return total;
	}

	/**
	 * Chris's current (unboosted) level in the given skill. Must be called on
	 * the client thread.
	 */
	int getSkillLevel(Skill skill)
	{
		return client.getRealSkillLevel(skill);
	}

	/**
	 * Whether the given quest is finished, in progress, or not started yet.
	 * Runs a client script under the hood, so - like the skill level above -
	 * this must be called on the client thread.
	 */
